    total (a[0..i+1]);
    total (b);
    total (b[0..|b|-1]) + b[|b|-1];
    total (b[0..|b|-1]) + a[i];
    {assert (b[0..|b|-1] == a[0..i]);}
    total (a[0..i]) + a[i];
  }
}

method Total (a: seq<nat>) returns (r:nat)
  ensures r == total (a[0..|a|]); 
{
  var i := 0;
  r := 0;
  while i < |a|
    invariant 0 <= i <= |a|;
    invariant r == total (a[0..i]);
